OUT={}
def add(id,raw,l3,io,domain):OUT[id]={'canonical_raw':raw,'canonical_l3':l3,'io_protocol':io,'shared_constraints':domain+' All numeric inputs are integers. Indices are zero-based unless explicitly stated otherwise.'}
P='998244353'
arr='Input N Q; then N array values a_0..a_(N-1); then Q query lines. Output one answer per query that requests a value, in chronological order.'
static='Input N Q; then N array values a_0..a_(N-1); then Q query lines. Output one integer per query in input order.'
nonnegative='N,Q>=1; initial values are in[0,10^9].'
add('staticrmq','For each query l r, return min(a_i : l<=i<r). The array is fixed.','For each query l r, return max(a_i : l<=i<r). The array is fixed.',static+' Each query is l r.',nonnegative+' Every query satisfies0<=l<r<=N.')
add('range_kth_smallest','For each query l r k, sort the multiset of values a_l..a_(r-1) in ascending order and return its zero-based rankk element. Repeated values retain their multiplicities.','For each query l r k, sort the multiset of values a_l..a_(r-1) in descending order and return its zero-based rankk element. Repeated values retain their multiplicities.',static+' Each query is l r k.',nonnegative+' 0<=l<r<=N and0<=k<r-l.')
add('longest_increasing_subsequence','Find a longest subsequence whose VALUES are strictly increasing. Chosen indices must increase strictly. Return any optimal sequence of indices.','Find a longest subsequence whose VALUES are nondecreasing. Chosen indices must increase strictly. Return any optimal sequence of indices.','Input N, then N integers a_i. Output maximum lengthK on the first line and K chosen indices i_0<...<i_(K-1) on the second. Any optimum is accepted.','N>=1;0<=a_i<=10^9.')
add('line_add_get_min','Maintain a collection of lines y=a*x+b. Operation0 a b adds that line. Operation1 p returns the minimum value a*p+b over every currently stored line, including the initial lines.','Maintain a collection of lines y=a*x+b. Operation0 a b adds that line. Operation1 p returns the maximum value a*p+b over every currently stored line, including the initial lines.','Input N Q; N lines a_i b_i; Q operations0 a b or1 p. Output one exact integer per type1 operation.','N,Q>=1; all slopes and query coordinates have absolute value<=10^9; all intercepts have absolute value<=10^18. Lines are never removed.')
add('segment_add_get_min','Maintain line segments y=a*x+b with domain l<=x<r. Operation0 l r a b inserts a segment. Operation1 p returns the minimum value a*p+b among segments coveringp, or the token INFINITY if no segment coversp.','Maintain line segments y=a*x+b with domain l<=x<r. Operation0 l r a b inserts a segment. Operation1 p returns the maximum value a*p+b among segments coveringp, or the token INFINITY if no segment coversp.','Input N Q; N initial segments l_i r_i a_i b_i; Q operations0 l r a b or1 p. Output one exact integer or INFINITY per type1 operation.','N,Q>=1;-10^9<=l<r<=10^9; slopes and query coordinates have absolute value<=10^9; intercepts have absolute value<=10^18.')
add('cartesian_tree','Build the binary Cartesian tree on the distinct array values: the index of the minimum value is the root, and the left and right intervals are processed recursively. The inorder vertex order is0..N-1. Output the parent of every vertex.','Build the binary Cartesian tree on the distinct array values: the index of the maximum value is the root, and the left and right intervals are processed recursively. The inorder vertex order is0..N-1. Output the parent of every vertex.','Input N and N values a_i. Output N parents p_i. The rootr has p_r=r; all other parents are zero-based vertex indices.','N>=1;0<=a_i<=10^9; all a_i are distinct.')
add('minimum_spanning_tree','Find a spanning tree of minimum total edge weight in the given connected undirected weighted graph. A spanning tree uses N-1 distinct edges, connects all vertices, and has no cycle.','Find a spanning tree of maximum total edge weight in the given connected undirected weighted graph. A spanning tree uses N-1 distinct edges, connects all vertices, and has no cycle.','Input N M, then M lines u_i v_i w_i, indexed0..M-1. Output the optimum total weightX, then N-1 edge indices of an attaining spanning tree. Any optimum and any edge order are accepted. ForN=1 outputX=0 and no edge indices.','N>=1;M>=N-1;0<=u_i,v_i<N;0<=w_i<=10^9. Self-loops and parallel edges are allowed. The graph is connected.')
add('assignment','Find a permutationp of0..N-1 minimizing sum overi of a_(i,p_i). Return both the optimum cost and an attaining permutation.','Find a permutationp of0..N-1 maximizing sum overi of a_(i,p_i). Return both the optimum cost and an attaining permutation.','Input N, then N rows of N matrix entries. Output optimum costX on the first line and permutation p_0..p_(N-1) on the second. Any optimum is accepted.','N>=1; each matrix entry is in[-10^9,10^9].')
add('static_range_frequency','For each query l r x, count indicesi with l<=i<r and a_i=x.','For each query l r x, count indicesi with l<=i<r and a_i<x.',static+' Each query is l r x. Empty ranges return0.','N,Q>=0;0<=a_i,x<=10^9;0<=l<=r<=N.')
add('static_range_inversions_query','For every query l r, count ordered index pairs(i,j) with l<=i<j<r and a_i>a_j.','For every query l r, count ordered index pairs(i,j) with l<=i<j<r and a_i>=a_j.',static+' Each query is l r.',nonnegative+' 0<=l<r<=N.')
add('range_add_range_min','Operation0 l r x addsx to every a_i with l<=i<r. Operation1 l r returns the minimum current value in that range.','Operation0 l r x addsx to every a_i with l<=i<r. Operation1 l r returns the maximum current value in that range.',arr+' Operation lines are0 l r x or1 l r.','N,Q>=1; each initial a_i and updatex is in[-10^9,10^9];0<=l<r<=N. Updated values are not clipped to the input range.')
add('set_xor_min','Start with an empty setS. Operation0 x insertsx if absent;1 x removesx if present;2 x outputs min(y XOR x : y inS). XOR is bitwise exclusive OR.','Start with an empty setS. Operation0 x insertsx if absent;1 x removesx if present;2 x outputs max(y XOR x : y inS). XOR is bitwise exclusive OR.','Input Q then Q lines t x with t in{0,1,2}. Output one integer per type2 operation.','Q>=1;0<=x<2^30. The set is nonempty for every type2 query. Duplicate insertion and deletion of an absent key do nothing.')
for id,replace,syntax in [('point_set_range_composite','Operation0 p c d replaces only function f_p by z->c*z+d.','0 p c d'),('range_set_range_composite','Operation0 l r c d replaces every f_i with l<=i<r by z->c*z+d.','0 l r c d')]:
 raw='Maintain functions f_i(z)=a_i*z+b_i over residues modulo998244353. '+replace+' For operation1 l r x, start withx and apply f_l,f_(l+1),...,f_(r-1) in that order, reducing modulo998244353; output the final residue.'
 l3='Maintain functions f_i(z)=a_i*z+b_i over residues modulo998244353. '+replace+' For operation1 l r x, start withx and apply f_(r-1),f_(r-2),...,f_l in that order, reducing modulo998244353; output the final residue.'
 add(id,raw,l3,'Input N Q; N coefficient pairs a_i b_i; Q operation lines '+syntax+' or1 l r x. Output one canonical residue per type1 query.','N,Q>=1;1<=a_i,c<998244353;0<=b_i,d,x<998244353;0<=l<r<=N; '+(' Point index p satisfies 0<=p<N.' if id=='point_set_range_composite' else ''))
for id,isdeque in [('queue_operate_all_composite',False),('deque_operate_all_composite',True)]:
 edits='Operation0 a b prepends z->a*z+b;1 a b appends it;2 removes the first function;3 removes the last function.' if isdeque else 'Operation0 a b appends z->a*z+b;1 removes the first function.'
 query='4 x' if isdeque else '2 x'
 begin='Start with an empty ordered sequence of affine functions modulo998244353. '+edits
 raw=begin+' For query'+query+', start withx and apply all functions from FRONT TO BACK, outputting the final residue. An empty sequence returnsx.'
 l3=begin+' For query'+query+', start withx and apply all functions from BACK TO FRONT, outputting the final residue. An empty sequence returnsx.'
 add(id,raw,l3,'Input Q followed by Q operation lines in the stated formats. Output one canonical residue per query'+query+'.','Q>=1;1<=a<998244353;0<=b,x<998244353. A removal operation is issued only when the sequence is nonempty.')
add('point_add_range_sum','Operation0 p x addsx to a_p. Operation1 l r returns the sum of current values a_l..a_(r-1).','Operation0 p x addsx to a_p. Operation1 l r returns the maximum current value among a_l..a_(r-1).',arr+' Operation lines are0 p x or1 l r.','N,Q>=1;0<=initial a_i,x<=10^9;0<=p<N;0<=l<r<=N. Later values may exceed10^9.')
add('vertex_add_path_sum','On the fixed tree, operation0 p x addsx to vertexp. Operation1 u v returns the sum of vertex values along the unique path fromu tov, INCLUDING both endpoints.','On the fixed tree, operation0 p x addsx to vertexp. Operation1 u v returns the maximum vertex value along the unique path fromu tov, INCLUDING both endpoints.','Input N Q; N initial vertex values; N-1 undirected edges u_i v_i; Q operations0 p x or1 u v. Output one exact integer per type1 query.','N,Q>=1; vertex indices are0..N-1; edges form a tree;0<=initial values,x<=10^9. Query endpoints may coincide; such a path consists of one vertex.')
add('vertex_add_subtree_sum','The tree is rooted at vertex0. Operation0 u x addsx to vertexu. Operation1 u returns the sum of values in the subtree rooted atu, INCLUDINGu itself.','The tree is rooted at vertex0. Operation0 u x addsx to vertexu. Operation1 u returns the maximum value in the subtree rooted atu, INCLUDINGu itself.','Input N Q; N initial values; N-1 parents p_1..p_(N-1); Q operations0 u x or1 u. Output one exact integer per type1 query.','N,Q>=1;0<=p_i<i for1<=i<N;0<=u<N;0<=initial values,x<=10^9. ForN=1 the parent list is empty.')
add('range_reverse_range_sum','Operation0 l r reverses the current subsequence a_l..a_(r-1). Operation1 l r returns the sum of that current range, with empty-range sum0.','Operation0 l r reverses the current subsequence a_l..a_(r-1). Operation1 l r returns max({0} union {a_i:l<=i<r}); thus an empty range returns0.',arr+' Every operation line is t l r, with t in{0,1}.','N,Q>=0;0<=a_i<=10^9;0<=l<=r<=N. Empty sequences and empty updates/queries are allowed.')
add('range_affine_range_sum','Operation0 l r b c replaces each a_i with b*a_i+c for l<=i<r. Operation1 l r returns sum(a_i:l<=i<r) modulo998244353. All arithmetic may be reduced modulo998244353.','Operation0 l r b c replaces each a_i with b*a_i+c for l<=i<r. Operation1 l r returns sum(a_i^2:l<=i<r) modulo998244353. All arithmetic may be reduced modulo998244353.',arr+' Operations are0 l r b c or1 l r. Print canonical residues in[0,998244352].','N,Q>=1;0<=initial a_i,c<998244353;1<=b<998244353;0<=l<r<=N.')
add('static_range_count_distinct','For each query l r, count the number of distinct values occurring in a_l..a_(r-1).','For each query l r, count the distinct values that occur EXACTLY ONCE in a_l..a_(r-1). Values occurring twice or more contribute0.',static+' Each query is l r. Empty ranges return0.','N,Q>=0;0<=a_i<=10^9;0<=l<=r<=N.')
setops='Operation0 x insertsx if absent;1 x removesx if present;3 x counts members<=x;4 x returns the largest member<=x or-1 if absent;5 x returns the smallest member>=x or-1 if absent.'
add('ordered_set','Maintain the initial setS. '+setops+' Operation2 x returns the x-th SMALLEST member (one-based rank), or-1 if x>|S|.','Maintain the initial setS. '+setops+' Operation2 x returns the x-th LARGEST member (one-based rank), or-1 if x>|S|.','Input N Q; N initial keys in strictly increasing order; Q operations t x with0<=t<=5. Output one integer per operation of type2,3,4,5.','N>=0,Q>=1;0<=initial keys,x<=10^9; type2 requiresx>=1. Duplicate insertion and absent-key deletion do nothing.')
base='S initially contains exactly indices whose bit inT is1. Operation0 k insertsk if absent;1 k removesk if present;2 k returns1 ifk is present and0 otherwise;4 k returns the largest member<=k or-1 if none exists.'
add('predecessor_problem',base+' Operation3 k returns the smallest member>=k, or-1 if none exists.',base+' Operation3 k returns the smallest member STRICTLY GREATER THANk, or-1 if none exists.','Input N Q; a lengthN bitstringT; Q operations t k with0<=t<=4. Output one integer for each operation of type2,3,4.','N,Q>=1;0<=k<N;T contains only0 and1. The set may be empty.')
add('associative_array','An integer-indexed array is initially zero at every nonnegative index. Operation0 k v SETS a[k]=v; operation1 k prints the current a[k].','An integer-indexed array is initially zero at every nonnegative index. Operation0 k v ADDS v to a[k]; operation1 k prints the current a[k]. Values accumulate without a modulus and may exceed64-bit integer range.','Input Q then Q operations0 k v or1 k. Output the exact nonnegative decimal integer for each type1 operation.','Q>=1;0<=k,v<=10^18. Reading a key never written returns0.')
add('majority_voting','Operation0 p x assigns a_p=x. Operation1 l r returns a value whose frequencyf in a_l..a_(r-1) satisfies2*f>r-l, or-1 if no such value exists.','Operation0 p x assigns a_p=x. Operation1 l r returns a value whose frequencyf in a_l..a_(r-1) satisfies3*f>2*(r-l), or-1 if no such value exists.',arr+' Operations are0 p x or1 l r.','N,Q>=1;0<=initial a_i,x<=10^9;0<=p<N;0<=l<r<=N. At most one value can satisfy either stated threshold.')
add('persistent_queue','Let versionS_-1 be empty. For operationi of form0 t x, createS_i by appendingx toS_t. For form1 t, createS_i by removing the FRONT element ofS_t and print that removed element. Previously created versions never change.','Let versionS_-1 be empty. For operationi of form0 t x, createS_i by appendingx toS_t. For form1 t, createS_i by removing the BACK element ofS_t and print that removed element. Previously created versions never change.','Input Q; Q operations indexed i=0..Q-1, each0 t x or1 t. Output one removed value per type1 operation.','Q>=1;-1<=t<i;0<=x<=10^9. Every referenced version for type1 is nonempty.')
for id,rawpred,newpred in [('bitwise_and_convolution','i AND j=k','i OR j=k'),('bitwise_xor_convolution','i XOR j=k','i AND j=k'),('subset_convolution','(i AND j)=0 and (i OR j)=k','i OR j=k')]:
 intro='Given arraysa,b indexed0..2^N-1, for everyk in that index range compute c_k=sum(a_i*b_j over all ordered pairs(i,j) satisfying '
 ending=') modulo998244353. AND, OR and XOR denote the corresponding bitwise operations.'
 add(id,intro+rawpred+ending,intro+newpred+ending,'Input N;2^N coefficientsa;2^N coefficientsb. Output2^N canonical residues c_0..c_(2^N-1) in increasing index order.','N>=0;0<=a_i,b_i<998244353. Repeated coefficients are permitted; all index pairs are ordered.')
for id,rp,np in [('gcd_convolution','gcd','lcm'),('lcm_convolution','lcm','gcd')]:
 def desc(f):return 'Given arraysa,b indexed1..N, compute c_k=sum(a_i*b_j over ordered pairs1<=i,j<=N with '+f+'(i,j)=k) modulo998244353, for everyk=1..N. Only theseN coefficients are output; pairs whose '+f+' exceedsN contribute to no output. gcd means greatest common divisor and lcm means least common multiple.'
 add(id,desc(rp),desc(np),'Input N;N coefficientsa_1..a_N;N coefficientsb_1..b_N. OutputN canonical residues c_1..c_N in increasing index order.','N>=1;0<=a_i,b_i<998244353.')
add('sum_of_floor_of_linear','For each(N,M,A,B), compute the exact integer sum over0<=i<N of floor((A*i+B)/M), where floor is rounding down to an integer.','For each(N,M,A,B), compute the exact integer sum over0<=i<N of ceil((A*i+B)/M), where ceil is rounding up to an integer.','Input T; then T lines N M A B. Output one exact integer per line.','T,N>=1;1<=M<=10^9;0<=A,B<M. No floating-point rounding is intended.')
add('kth_root_integer','For each nonnegativeA and positiveK, output the GREATEST nonnegative integerr satisfying r^K<=A.','For each nonnegativeA and positiveK, output the LEAST nonnegative integerr satisfying r^K>=A.','Input T;T pairs A K. Output one exact integer root per case.','T>=1;0<=A<2^64;1<=K<=64. Integer powers and comparisons are exact, including at unsigned64-bit boundaries.')
add('rectangle_sum','For each rectangle query l d r u, sum weights of all input point occurrences satisfying l<=x<r and d<=y<u. Coincident points retain separate weights.','For each rectangle query l d r u, sum weights of all input point occurrences satisfying l<=x<=r and d<=y<u. Coincident points retain separate weights.','Input N Q;N weighted points x_i y_i w_i;Q rectangles l d r u. Output one exact weighted sum per rectangle.','N,Q>=1;0<=x_i,y_i,w_i<=10^9;0<=l<r<=10^9;0<=d<u<=10^9.')
add('point_add_rectangle_sum','Initially store the given weighted points. Operation0 x y w inserts a new point occurrence with weightw, even if its coordinates already exist. Operation1 l d r u returns the sum of weights of stored occurrences with l<=x<r and d<=y<u.','Initially store the given weighted points. Operation0 x y w inserts a new point occurrence with weightw, even if its coordinates already exist. Operation1 l d r u returns the sum of weights of stored occurrences with l<=x<=r and d<=y<u.','Input N Q;N initial points x_i y_i w_i;Q operations0 x y w or1 l d r u. Output one exact integer per type1 operation.','N,Q>=1; coordinates and weights are in[0,10^9];0<=l<r<=10^9;0<=d<u<=10^9. Updates and queries are processed chronologically.')
add('rectangle_add_point_get','Maintain weighted rectangles, each covering l<=x<r and d<=y<u. Operation0 l d r u w inserts a new rectangle occurrence of weightw. Operation1 x y sums weights of all currently stored rectangles covering that point.','Maintain weighted rectangles, each covering l<=x<=r and d<=y<u. Operation0 l d r u w inserts a new rectangle occurrence of weightw. Operation1 x y sums weights of all currently stored rectangles covering that point.','Input N Q;N initial rectangles l_i d_i r_i u_i w_i;Q operations0 l d r u w or1 x y. Output one exact weighted sum per type1 operation.','N,Q>=1;0<=l<r<=10^9;0<=d<u<=10^9;0<=query x,query y,w<=10^9. Initial and inserted rectangles obey the same bounds. Identical rectangles remain separate weighted occurrences.')
add('number_of_substrings','Count the number of DISTINCT NONEMPTY contiguous substrings ofS. Equal strings at different positions are counted only once.','Count the number of DISTINCT NONEMPTY contiguous substrings ofS whose length is EVEN. Equal strings at different positions are counted only once.','Input one stringS. Output one integer.','S is nonempty and consists only of lowercase English letters.')
add('wildcard_pattern_matching','For every offseti with0<=i<=|S|-|T|, compareS[i:i+|T|] withT. The alignment matches iff at each position the two characters are equal OR the text character is* OR the pattern character is*. Each* matches exactly one character, not a variable-length string.','For every offseti with0<=i<=|S|-|T|, compareS[i:i+|T|] withT. The alignment matches iff at each position the pattern character is* OR the text character equals the pattern character. A pattern* matches any single character, including a text*. A text* has no wildcard power and fails against every lowercase pattern letter.','Input textS then patternT as two whitespace-separated strings. Output ONE BITSTRING of length |S|-|T|+1, with no spaces: characteri is1 for a matching alignment and0 otherwise.','1<=|T|<=|S|. Both strings contain only lowercase English letters and*.')
lyndon='A nonempty word is Lyndon if it is strictly lexicographically smaller than each of its nonempty proper suffixes. A Lyndon factorization partitionsS into a sequence of Lyndon words in NONINCREASING lexicographic order. Lexicographic comparisons treat a proper prefix as smaller.'
add('lyndon_factorization',lyndon+' Use the alphabet ordera<b<...<z and output the unique factor boundaries.',lyndon+' Use the REVERSED alphabet orderz<y<...<a and output the unique factor boundaries. Characters inS itself are not rewritten.','Input one stringS of lengthN. Output boundary indices0=a_0<a_1<...<a_k=N; factorj isS[a_j:a_(j+1)]. Output only thosek+1 indices, without a preceding count.','S is nonempty and consists only of lowercase English letters.')
