for id,d in OUT.items():
 p=sources[id];d['source_task_path']=str(p.relative_to(root));d['source_task_sha256']=hashlib.sha256(p.read_bytes()).hexdigest();d['statement_review']='Agent-authored standalone restatement checked against archived task.md, parameter domains, mutation SPEC and executable protocols; no original examples reused.'
